:root {
  color: #172b4d;
  background: #f4f5f7;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-synthesis: none;
}

body { margin: 0; }
.container { box-sizing: border-box; max-width: 760px; margin: 64px auto; padding: 32px; background: white; border-radius: 8px; box-shadow: 0 2px 8px #091e4220; }
h1 { margin: 0 0 28px; font-size: 2rem; }
form { display: flex; align-items: end; gap: 12px; margin-bottom: 28px; }
label { display: grid; flex: 1; gap: 8px; font-weight: 600; }
input { box-sizing: border-box; width: 100%; padding: 10px 12px; border: 1px solid #a5adba; border-radius: 4px; font: inherit; }
button { padding: 10px 16px; border: 0; border-radius: 4px; background: #0c66e4; color: white; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #0055cc; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 0; border-top: 1px solid #dfe1e6; }
.project-name { overflow-wrap: anywhere; }
.alert { margin: 0 0 16px; color: #ae2e24; }
.back-button { margin-bottom: 24px; }
@media (max-width: 600px) { .container { margin: 16px; padding: 24px; } form { align-items: stretch; flex-direction: column; } }

